    // Key not found in either row, so the value should already be None
    // We need to temporarily remove and re-add the rows to get access to their tokens
    let hash_row1 = hash1(key);
    let hash_row2 = hash2(key);
    let is_h1x_hash1 = h1x as nat == hash_row1;
    let tracked mut r1;
    let tracked mut r2;
    if is_h1x_hash1 {
        r1 = lock1x.rows.tracked_remove(hash_row1);
        r2 = lock2x.rows.tracked_remove(hash_row2);
