            self.instance.query_none(key, &mpt, &r1.token, &r2.token);
        }
        Tracked(Commit(mpt))
    });

    // Re-insert the rows unchanged
    if is_h1x_hash1 {
        lock1x.rows.tracked_insert(hash_row1, r1);
        lock2x.rows.tracked_insert(hash_row2, r2);
    } else {
        lock2x.rows.tracked_insert(hash_row1, r1);
        lock1x.rows.tracked_insert(hash_row2, r2);
    }

    handle1x.release_write(Tracked(lock1x));
    handle2x.release_write(Tracked(lock2x));
}

